args.sparql:
SELECT DISTINCT ?mother ?label ?dbpDeathDate ?dboDeathDate ?dbpDeathYear ?dbpDeathPlace WHERE {
  BIND(dbr:Ermengarde_of_Tours AS ?mother)
  OPTIONAL { ?mother rdfs:label ?label . FILTER(lang(?label) = 'en') }
  OPTIONAL { ?mother dbp:deathDate ?dbpDeathDate }
  OPTIONAL { ?mother dbo:deathDate ?dboDeathDate }
  OPTIONAL { ?mother dbp:deathYear ?dbpDeathYear }
  OPTIONAL { ?mother dbp:deathPlace ?dbpDeathPlace }
}

SELECT ?mother ?label ?years WHERE {
  BIND(dbr:Ermengarde_of_Tours AS ?mother)
  OPTIONAL { ?mother rdfs:label ?label . FILTER(lang(?label)='en') }
  OPTIONAL { ?mother dbp:years ?years }
}

SELECT ?lothair ?mother ?motherLabel ?abstract WHERE {
  BIND(dbr:Lothair_II AS ?lothair)
  ?lothair dbp:mother ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = 'en') }
  OPTIONAL { ?mother dbo:abstract ?abstract . FILTER(lang(?abstract) = 'en') }
}

